import React, { useState, useEffect } from "react";
import axios from "axios";
import "./GroupManagement.css";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import StudentSidebar from "../components/StudentSidebar";

const GroupManagement = () => {
  const [group, setGroup] = useState(null);
  const [members, setMembers] = useState([]);
  const [supervisor, setSupervisor] = useState(null);
  const [evaluator, setEvaluator] = useState(null);
  const [activityLogs, setActivityLogs] = useState([]);
  const [isAdmin, setIsAdmin] = useState(false); // Assuming this is checked via login system

  const groupNo = "G-37"; // Static group number for now, could be dynamic in real use

  // Fetch group details, students, supervisor, and evaluator data from the backend
  useEffect(() => {
    // Fetch the group details from backend
    axios
      .get(`http://localhost:5000/api/group/${groupNo}`)
      .then((response) => {
        setGroup(response.data);

        // Fetch student details for each student in the group
        const fetchStudents = async () => {
          const studentDetails = await Promise.all(
            response.data.studentsRegno.map(async (regNo) => {
              const studentResponse = await axios.get(`http://localhost:5000/api/student/${regNo}`);
              return studentResponse.data; // Add full student details
            })
          );
          setMembers(studentDetails); // Update members state
        };

        fetchStudents();

        // Fetch supervisor details
        axios
          .get(`http://localhost:5000/api/facultyAdvisor/${response.data.supervisorID}`)
          .then((supervisorResponse) => setSupervisor(supervisorResponse.data))
          .catch((error) => console.error("Error fetching supervisor data:", error));

        // Fetch evaluator details
        axios
          .get(`http://localhost:5000/api/evaluator/${response.data.evaluatorID}`)
          .then((evaluatorResponse) => setEvaluator(evaluatorResponse.data))
          .catch((error) => console.error("Error fetching evaluator data:", error));
      })
      .catch((error) => console.error("Error fetching group data:", error));
  }, [groupNo]);

  // Function to disband the group (DELETE request)
  const disbandGroup = async () => {
    try {
      // Update students' isGrouped attribute to false
      await Promise.all(
        members.map(async (member) => {
          await axios.put(`http://localhost:5000/api/student/${member.regNo}`, {
            isGrouped: false,
          });
        })
      );
      // Then disband the group
      await axios.delete(`http://localhost:5000/api/group/${groupNo}`);
      alert("Group disbanded successfully.");
      setGroup(null); // Clear group data from state
      setMembers([]); // Clear members from state
    } catch (error) {
      console.error("Error disbanding group", error);
      alert("Failed to disband group");
    }
  };

  // Function to update the role of a member
  const updateRole = (id, newRole) => {
    const updatedMembers = members.map((member) =>
      member.regNo === id ? { ...member, role: newRole } : member
    );
    setMembers(updatedMembers);
    setActivityLogs([
      ...activityLogs,
      {
        id: activityLogs.length + 1,
        message: `Role updated for ${id}`,
        timestamp: new Date().toLocaleString(),
      },
    ]);
  };

  return (
    <div className="group-management-container">
      <Navbar />
      <div className="content-wrapper">
        <StudentSidebar />
        <div className="main-content">
          <h1 className="title">Group Management</h1>

          {/* Group Information Section */}
          {group && (
            <div className="group-details">
              <h2>Group Details</h2>
              <div className="group-info">
                <p><strong>Group Number:</strong> {group.groupNo}</p>
                <p><strong>Project Title:</strong> {group.projectID}</p>
                <p><strong>Supervisor:</strong> {supervisor ? supervisor.name : "Loading..."}</p>
                <p><strong>Evaluator:</strong> {evaluator ? evaluator.name : "Loading..."}</p>
              </div>
            </div>
          )}

          {/* Disband Group Button */}
          {isAdmin && (
            <button onClick={disbandGroup} className="disband-button">
              Disband Group
            </button>
          )}

          {/* Team Members Section */}
          <div className="profiles-section">
            <h2>Team Member Profiles</h2>
            <ul>
              {members.map((member) => (
                <li key={member.regNo} className="member-card">
                  <img src={member.profilePic || "https://via.placeholder.com/150"} alt={member.name} className="profile-pic" />
                  <div className="member-info">
                    <p><strong>Name:</strong> {member.studentName}</p>
                    <p><strong>Role:</strong> {member.role || "Unassigned"}</p>
                    <p><strong>Email:</strong> {member.email}</p>
                    <p><strong>Skills:</strong> {member.skills || "N/A"}</p>

                    {/* Role update (if admin) */}
                    {isAdmin && (
                      <label>
                        Update Role:
                        <select
                          value={member.role || "Unassigned"}
                          onChange={(e) => updateRole(member.regNo, e.target.value)}
                        >
                          <option value="Developer">Developer</option>
                          <option value="Tester">Tester</option>
                          <option value="Manager">Manager</option>
                        </select>
                      </label>
                    )}
                  </div>
                </li>
              ))}
            </ul>
          </div>

          {/* Activity Logs Section */}
          <div className="logs-section">
            <h2>Activity Logs</h2>
            <ul>
              {activityLogs.map((log) => (
                <li key={log.id} className="log-item">
                  <span className="log-timestamp">{log.timestamp}</span> - {log.message}
                </li>
              ))}
            </ul>
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default GroupManagement;
